# Figure 5 step 3 (post hoc diagnostic, prompted by the single-cell result that GALNT16 is detected in <1% of malignant cells):
# is the bulk TCGA-PAAD GIScore association a composition (non-tumor content) effect?  Uses frozen scores; no refitting.
suppressPackageStartupMessages({library(data.table); library(survival)})
root <- "${PROJECT_ROOT}"; r4 <- file.path(root, "04_results/2026-10-12_Figure4_GALNT_run01"); r5 <- file.path(root, "04_results/2026-10-12_Figure5_GALNT_run01"); dir.create(r5, showWarnings = FALSE)
tr <- fread(file.path(r4, "training_scores.csv")); E <- readRDS(file.path(r4, "tcga_paad_ductal_expr_allgenes.rds"))[, tr$sample]; Zs <- t(scale(t(E)))
sg <- list(`Stromal (CAF)` = c("COL1A1", "COL1A2", "COL3A1", "DCN", "LUM", "FAP"), Immune = c("PTPRC", "CD3E", "CD8A", "CD68", "CD4", "CD19"), Acinar = c("PRSS1", "CPA1", "CELA3A", "CTRB1", "PNLIP", "CEL"), Endocrine = c("INS", "GCG", "SST", "PPY", "CHGA", "PCSK1"), Neural = c("SNAP25", "SYT1", "STMN2", "NEFL", "NRXN1", "GAP43"), `Tumor epithelial` = c("KRT7", "KRT19", "EPCAM", "KRT8", "KRT18", "MUC1"))
S <- sapply(sg, function(g) colMeans(Zs[intersect(g, rownames(Zs)), , drop = FALSE])); S <- data.frame(S, check.names = FALSE); S$GALNT16 <- E["GALNT16", ]; S$GALNT14 <- E["GALNT14", ]; S$GIScore <- tr$risk
cor_t <- rbindlist(lapply(c("GALNT16", "GALNT14", "GIScore"), function(x) rbindlist(lapply(names(sg), function(s) { ct <- cor.test(S[[x]], S[[s]], method = "spearman", exact = FALSE); data.table(variable = x, signature = s, rho = unname(ct$estimate), p = ct$p.value) })))); cor_t[, BH := p.adjust(p, "BH")]; fwrite(cor_t, file.path(r5, "H_tcga_composition_correlations.csv"))
S$time <- tr$time; S$event <- tr$event; S$risk_z <- as.numeric(scale(S$GIScore)); S$nontumor_PC1 <- prcomp(S[, c("Stromal (CAF)", "Immune", "Acinar", "Endocrine", "Neural")], scale. = TRUE)$x[, 1]; if (cor(S$nontumor_PC1, S$`Tumor epithelial`) > 0) S$nontumor_PC1 <- -S$nontumor_PC1  # higher = more non-tumor
cx <- function(vars, nm) { f <- coxph(as.formula(paste("Surv(time, event) ~", paste(sprintf("`%s`", vars), collapse = "+"))), S); s <- summary(f); i <- match("risk_z", rownames(s$coefficients)); data.table(model = nm, HR = s$coefficients[i, 2], lo = s$conf.int[i, 3], hi = s$conf.int[i, 4], p = s$coefficients[i, 5], n = f$n) }
sens <- rbind(cx("risk_z", "GIScore alone"), cx(c("risk_z", "Tumor epithelial"), "+ tumor-epithelial score"), cx(c("risk_z", "nontumor_PC1"), "+ non-tumor content (PC1 of 5 signatures)"), cx(c("risk_z", "Stromal (CAF)", "Immune", "Acinar", "Endocrine", "Neural", "Tumor epithelial"), "+ all 6 compartment signatures"))
f1 <- coxph(Surv(time, event) ~ nontumor_PC1, S); sens <- rbind(sens, data.table(model = "non-tumor PC1 alone (prognostic?)", HR = summary(f1)$coefficients[2], lo = summary(f1)$conf.int[3], hi = summary(f1)$conf.int[4], p = summary(f1)$coefficients[5], n = f1$n)); fwrite(sens, file.path(r5, "H_tcga_composition_adjusted_cox.csv")); options(width = 200); print(cor_t); print(sens)
fwrite(S, file.path(r5, "H_tcga_composition_table.csv"))
